 for(auto& s:data.symbols){auto section=b.section(s.va);if(!section||!section->executable)continue;auto end=add(section->va,section->memorySize);if(s.end>end)s.end=end;Json row={{"address",hex(s.va)},{"end",hex(s.end)},{"name",s.name}};auto cost=row.dump().size()+2;if(cost>stateLimit-persistedBytes){data.truncated=true;break;}persistedBytes+=cost;auto found=index.find(s.va);if(found!=index.end()){auto& f=functions[found->second];f.name=s.name;f.source="debug_symbol";if(s.end>s.va)f.end=s.end;}else functions.push_back({s.va,s.end,s.name,"debug_symbol"});symbolRows.push_back(std::move(row));}
 std::sort(functions.begin(),functions.end(),[](const auto& a,const auto& c){return a.va<c.va;});std::sort(data.lines.begin(),data.lines.end(),[](const auto& a,const auto& c){return a.va<c.va;});for(size_t i=0;i<data.lines.size();++i){auto& l=data.lines[i];if(l.end<=l.va){l.end=add(l.va,1);if(data.format=="pdb"){auto function=std::upper_bound(functions.begin(),functions.end(),l.va,[](Address v,const auto& f){return v<f.va;});if(function!=functions.begin()){--function;if(function->end>l.va)l.end=function->end;}if(i+1<data.lines.size()&&data.lines[i+1].va>l.va)l.end=std::min(l.end,data.lines[i+1].va);}}lineRows.push_back({{"address",hex(l.va)},{"end",hex(l.end)},{"file",l.file},{"line",l.number}});}
