std::optional<Json> callSymbolsTool(Engine& e,const std::string& name,const Json& args){if(name=="load_debug_symbols")return load(e,args);if(name=="list_debug_symbols"){require(e);Json rows=Json::array();auto& state=e.advancedState();if(!state.contains("symbols"))return Json{{"items",rows},{"total",0},{"loaded",false}};auto& debug=state["symbols"];auto offset=args.value("offset",size_t(0)),limit=args.value("limit",size_t(500));if(limit<1||limit>1000)throw std::runtime_error("limit must be from 1 to 1000");auto query=args.value("query",std::string());size_t total=0;for(auto& row:debug["symbols"]){cancel(e);if(row.at("name").get<std::string>().find(query)==std::string::npos)continue;if(total++>=offset&&rows.size()<limit)rows.push_back(row);}return Json{{"items",rows},{"total",total},{"offset",offset},{"loaded",true},{"format",debug["format"]},{"truncated",debug.value("truncated",false)}};}if(name=="lookup_source_line"){require(e);auto va=address(args.at("address"));auto& state=e.advancedState();if(state.contains("symbols")){const Json* best=nullptr;for(auto& row:state["symbols"]["lines"]){cancel(e);auto start=address(row.at("address")),end=address(row.at("end"));if(start<=va&&va<end&&(!best||start>address(best->at("address"))))best=&row;}if(best){auto result=*best;result["found"]=true;result["requested_address"]=hex(va);return result;}}return Json{{"found",false},{"address",hex(va)}};}return std::nullopt;}
